// Validação servidor-side (não confiar no front)
const b = $input.first().json.body || {};
const erros = [];
const ok = (v, lista) => lista.includes(v);

// honeypot + tempo mínimo (bots)
if ((b.empresa || '').trim() !== '') return [{ json: { valido: false, bot: true, erros: ['bot'] } }];
if (Number(b.tempo_preenchimento_s || 0) < 4) return [{ json: { valido: false, bot: true, erros: ['rapido_demais'] } }];

const nome = String(b.nome || '').trim().replace(/\s+/g, ' ').slice(0, 120);
if (nome.split(' ').length < 2) erros.push('nome');

const dig = String(b.whatsapp_original || '').replace(/\D/g, '');
if (!/^[1-9]{2}9\d{8}$/.test(dig)) erros.push('whatsapp');
const whatsapp_normalizado = '55' + dig;

let email = String(b.email || '').trim().toLowerCase().slice(0, 160);
if (email && !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) erros.push('email');
if (!email) email = null;

if (!ok(b.estado_civil, ['Solteiro(a)', 'Casado(a)'])) erros.push('estado_civil');
if (!ok(b.cnh_a, ['Sim', 'Não'])) erros.push('cnh_a');
if (!ok(b.ear, ['Sim', 'Não', 'Não sei informar'])) erros.push('ear');
if (!ok(b.atividade_app, ['Sim, com delivery (iFood, 99Food etc.)', 'Sim, com transporte de passageiros (Uber/99)', 'Sim, com delivery e transporte de passageiros', 'Não, ainda não trabalho com aplicativos'])) erros.push('atividade_app');
if (!ok(b.previsao_inicio, ['Em novembro, assim que estiver disponível', 'Nos próximos 30 dias', 'Daqui a 2 ou 3 meses', 'Estou apenas pesquisando'])) erros.push('previsao_inicio');
if (!ok(b.cidade, ['Americana', "Santa Bárbara d'Oeste", 'Nova Odessa', 'Outra cidade'])) erros.push('cidade');
if (b.consentimento !== true) erros.push('consentimento');

const limpa = (s, n) => (s == null ? null : String(s).slice(0, n));

return [{ json: {
  valido: erros.length === 0,
  erros,
  registro: {
    nome, estado_civil: b.estado_civil, whatsapp_original: String(b.whatsapp_original || '').slice(0, 20), whatsapp_normalizado, email,
    cnh_a: b.cnh_a, ear: b.ear, atividade_app: b.atividade_app, previsao_inicio: b.previsao_inicio, cidade: b.cidade,
    consentimento: true, consentimento_texto: limpa(b.consentimento_texto, 500), consentimento_versao: limpa(b.consentimento_versao, 20) || 'v1-2026-10',
    origem: limpa(b.origem, 60), campanha: limpa(b.campanha, 80), conteudo: limpa(b.conteudo, 80), user_agent: limpa(b.user_agent, 300)
  }
} }];
